import math


def ok(x, n):
    return x * x <= n


def largest_ok(n):
    lo, hi = 0, n + 1          # ok(lo) 는 참, ok(hi) 는 거짓
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if ok(mid, n):
            lo = mid           # 참이면 답은 mid 이상
        else:
            hi = mid           # 거짓이면 답은 mid 미만
    return lo


for n in [0, 1, 15, 16, 10**18, 10**18 - 1]:
    print(n, largest_ok(n), math.isqrt(n))

