#include <bits/stdc++.h>
using namespace std;

// n 은 0 이상 10^18 이하
long long largest_ok(long long n) {
    long long lo = 0, hi = 2000000000LL;    // ok(lo) 참, ok(hi) 거짓 (2*10^9 의 제곱 > 10^18)
    while (hi - lo > 1) {
        long long mid = lo + (hi - lo) / 2;
        if (mid <= n / mid) lo = mid;        // mid*mid <= n 을 곱하지 않고 확인 (mid >= 1)
        else hi = mid;
    }
    return lo;
}

int main() {
    long long ns[] = {0, 1, 15, 16, 1000000000000000000LL, 999999999999999999LL};
    for (long long n : ns) cout << n << ' ' << largest_ok(n) << '\n';
    return 0;
}

